/* Atelier — art therapy activities, part 5: loss and change, and more calm and grounding */
'use strict';

THERAPY.push(
  /* ---------- loss and change ---------- */
  { id: 'memory-box', th: 'change', n: 'Memory box', sum: 'Decorating a box to keep memories of someone or something special.',
    mins: 60, who: 'Ages 6 and up · one-to-one or small groups',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['collage', 'words', 'mixed'],
    depth: 3,
    mat: ['A small box with a lid, such as a shoebox or a gift box', 'Collage papers, magazines, fabric scraps and ribbon', 'PVA glue or glue sticks, and child-safe scissors', 'Felt-tips, textas or paint pens', 'Small cards for memory notes', 'Keepsakes or copies of photos from home (optional)'],
    purpose: 'A memory box gives memories of a person, a pet, a place or a time of life a safe home: it can be opened to remember and closed again for a rest. Choosing colours and making small things to go inside is a gentle, hands-on way to honour what mattered, at each person’s own pace.',
    steps: ['Talk about what a memory box is: a special place to keep memories of someone or something that matters, such as a person, a pet, a home or a time in life.', 'Each person chooses who or what their box is for, and can keep that private.', 'Decorate the outside with colours, patterns, pictures or words that feel right, using collage, paint pens or both.', 'Decorate the inside of the lid too, perhaps with a comforting colour or a favourite saying.', 'Make a few small things to go inside: drawings of happy or funny times, a list of things you did together, or notes that begin “I remember…”.', 'Add keepsakes from home if you have them, such as a copy of a photo, a ticket, a collar tag or a pressed flower.', 'Close the lid and decide where the box will live, and when you might like to open it.', 'Finish with something light and grounding together, such as a stretch, a slow breath or sharing a favourite song.'],
    prompts: ['Who or what would you like your box to hold memories of? You don’t have to tell anyone.', 'What colours remind you of them?', 'Happy, funny and everyday memories all belong here.', 'You can close the lid whenever you need a break.'],
    adapt: ['Young children: draw memories on small cards, with an adult writing their words, and decorate with stickers.', 'Some families and cultures, including many Aboriginal and Torres Strait Islander communities, may avoid names or photos of people who have died, so let the family guide what goes in.', 'Older adults: a box for a place, a job, a hobby or an era can be as meaningful as one for a person.', 'Anyone who would rather not make memories visible can decorate the outside only, and fill the box privately at home.', 'One-to-one: let the box grow over several lessons, with one new thing made each week.'],
    reflect: ['What was it like choosing what to put inside?', 'Which part of making the box did you enjoy most?', 'Where will your box live?'],
    care: `Memory boxes are often made after a death, but a pet, a home or a friend who moved away count too, so let each person choose. Focus on memories and love, never on how someone died. Tears and laughter are both normal; let people step out, keep their box private or stop at any time, and check in afterwards. ${CHILD_SAFE}` },
  { id: 'remembrance-stones', th: 'change', n: 'Remembrance stones', sum: 'Painting a smooth stone with a symbol for someone or something remembered.',
    mins: 40, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['nature', 'paint'],
    depth: 3,
    mat: ['Smooth stones from a garden centre, washed and dried', 'Acrylic paint or paint pens, and fine brushes', 'Cotton buds for dots', 'A shallow bowl, a tray of sand or a basket to gather the stones', 'Small cloth bags or tissues for taking stones home'],
    purpose: 'A stone is solid, smooth and lasting, which makes it a comforting thing to hold while remembering. Painting a colour, a symbol or a word for someone or something remembered, then placing the stones together, can be a quiet way to share remembering without needing to say much.',
    steps: ['Spread the stones on a cloth and invite everyone to choose one that feels right in their hand.', 'Hold the stone for a moment and think of who or what you’d like to remember: a person, a pet, a place, or a friend who moved away.', 'Choose a colour, a pattern or a small symbol that reminds you of them, such as a paw print, a flower, a favourite food or a musical note.', 'Paint a base colour if you like and let it dry, then add your symbol, some dots or a single word.', 'Paint a second stone if you’d like one to keep and one to give away or leave somewhere special.', 'When the stones are dry, gather them in a bowl or a tray of sand. Each person can say a name aloud, say it silently, or simply place their stone.', 'Sit together for a quiet moment, then take your stone home, or leave it in a garden bed or a pot plant.'],
    prompts: ['Choose the stone that feels right in your hand.', 'What colour or symbol reminds you of them?', 'You can say a name aloud, say it in your head, or just place your stone.', 'Remembering can feel sad and happy at the same time.'],
    adapt: ['Young children: use paint pens or stickers on larger stones, and remember a pet, a grandparent or a favourite place.', 'Limited grip: rest the stone in a ball of playdough to hold it still, and use paint pens rather than brushes.', 'Low vision: choose a large stone and add textured stickers or wrap it in wool, so the design can be felt.', 'Groups: make a remembrance corner, with the stones placed around a pot plant that stays in the room for a while.', 'Anyone who would rather not think about a loss today can paint a stone for a happy memory or a place they love.'],
    reflect: ['How did you choose your stone?', 'What was it like to hold it while you painted?', 'Where would you like your stone to be?'],
    care: `Let people choose who or what to remember: pets, places and friends who moved away count too. Focus on memories and love, never on how someone died, and welcome each family’s customs. Tears and laughter are both normal; let people step out, keep their stone private, and check in afterwards. Keep stones away from under-3s. ${CHILD_SAFE}` },
  { id: 'pop-up-goodbye-card', th: 'change', n: 'Pop-up goodbye card', sum: 'A pop-up card to say goodbye, thank you, or I’ll remember you.',
    mins: 40, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['mixed', 'draw', 'words'],
    depth: 3,
    mat: ['Two sheets of card per person, one a little larger than the other', 'Child-safe scissors, a ruler and a pencil', 'A glue stick', 'Felt-tips, textas or coloured pencils', 'Scrap paper for the pop-up picture', 'Envelopes (optional)'],
    purpose: 'Saying goodbye well matters, whether a friend is moving away, a teacher is leaving or someone has died. Making a card gives a goodbye or a thank-you a shape and somewhere to go, and the small surprise of a pop-up turns it into a gift, even if it can’t be posted.',
    steps: ['Talk about who a card could be for: a friend who’s moving, a teacher or carer who’s leaving, a pet, someone who has died, or even a home or a school.', 'Fold the smaller card in half. On the folded edge, cut two straight slits about 3 cm apart and 4 cm long.', 'Fold the flap between the slits back and forth to crease it, then open the card and push the flap through to the inside so it stands up like a step.', 'Draw a picture of a shared memory or something they love, small enough to stay hidden when the card is closed, and cut it out.', 'Glue the picture to the front of the step so it pops up when the card opens.', 'Write a message around it, perhaps starting with “Thank you for…”, “I’ll always remember…” or “I hope…”.', 'Glue the pop-up card inside the larger folded card, keeping the glue away from the step, then decorate the cover.', 'Decide what happens to the card: give it, post it, keep it somewhere special, or take it to a place that feels right.'],
    prompts: ['Who would you like to say goodbye or thank you to?', 'What’s a moment with them you’d like to remember?', 'Some cards are for giving and some are for keeping. Both are fine.', 'Write as much or as little as you like.'],
    adapt: ['Young children: an adult cuts the slits, and children draw the picture and say the message for an adult to write.', 'Limited grip: use pre-cut, pre-folded cards, and draw the picture straight onto the step.', 'Anyone who doesn’t want to write can draw the message, or glue in a word or two cut from a magazine.', 'Groups farewelling the same person: each makes a pop-up page, and the pages are glued back to back into one book.', 'Older adults: a card to a home, a neighbourhood or a job they’ve left can be as meaningful as one to a person.'],
    reflect: ['What was it like to choose the words for your card?', 'How did it feel when the pop-up worked?', 'What will you do with your card?'],
    care: `Let each person choose who the card is for; a teacher leaving or a pet counts as much as someone who died. A card for someone who has died can be kept or taken somewhere special, in whatever way suits the family’s beliefs. Strong feelings are normal: allow breaks, keep messages private unless offered, and check in afterwards. ${CHILD_SAFE}` },
  { id: 'then-and-now', th: 'change', n: 'Then and now', sum: 'A two-panel picture of life before and after a change, and what stayed the same.',
    mins: 45, who: 'Ages 7 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw', 'words'],
    depth: 2,
    mat: ['A3 paper, or two A4 sheets taped side by side', 'Pencils, felt-tips or textas', 'Coloured pencils, crayons or oil pastels', 'Magazines and a glue stick (optional)'],
    purpose: 'Big changes, such as moving house, starting a new school or a new baby in the family, can make life feel split into before and after. Drawing both sides helps make sense of what changed, and noticing what stayed the same, such as people, pets, skills and favourite things, can be steadying.',
    steps: ['Fold the paper in half, open it out, and rule a band about 4 cm wide down the fold.', 'Choose a change to draw. It can be big or small, recent or long ago, such as a new home, a new school, growing up or retiring.', 'In the left panel, draw “then”: a place, a day or a moment from before the change.', 'In the right panel, draw “now”: the same kind of place, day or moment as it is today.', 'In the middle band, draw or write the things that came with you or stayed the same, such as people, pets, skills, habits or favourite things.', 'Add colour and small details to each side, such as the weather, the light, or the sounds and smells you remember.', 'Step back, look at the whole page, and give it a title if you like.'],
    prompts: ['Choose a change you feel comfortable drawing today.', 'What’s different between the two sides? What’s the same?', 'What came with you from then to now?', 'Both sides can have good bits and hard bits.'],
    adapt: ['Young children: draw “when I was little” and “me now”, with a favourite toy or person in the middle.', 'Older adults: draw a street, a kitchen or a classroom from long ago beside the same kind of place today, which often sparks lively stories.', 'Anyone who doesn’t want to draw can use magazine pictures, or write a list on each side.', 'Add a third panel for “next” if someone would like to look ahead.'],
    reflect: ['Which side was easier to draw?', 'What did you put in the middle band?', 'What did you notice when you looked at the whole page?'],
    care: `Some changes are painful, such as separation, illness or a death in the family. Let people choose a lighter change, such as growing up, and never ask anyone to draw a hard event itself. Offer a break to anyone who seems upset, and close by looking at what stayed the same. ${CHILD_SAFE}` },
  { id: 'new-place-map', th: 'change', n: 'Map of my new place', sum: 'A map of a new home, school or suburb, with favourite spots marked.',
    mins: 40, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw', 'words'],
    depth: 1,
    mat: ['A large sheet of paper or butcher’s paper', 'Pencils, felt-tips or textas', 'Coloured pencils or crayons', 'Small stickers or sticky dots', 'A printed street map or floor plan to work from (optional)'],
    purpose: 'Moving to a new house, school, suburb or aged care home can feel confusing at first. Drawing a map from memory helps people get their bearings, notice how much they already know, and mark the spots that feel friendly, so a strange place can start to feel like their own.',
    steps: ['Choose the new place to map: a home, a school, a street, a suburb or an aged care home.', 'Start with a place you know well, such as your front door, your classroom or your room, and draw it in the middle of the page.', 'Add what’s around it: paths, rooms, streets, shops, parks and the way to the bus stop.', 'Mark your favourite spots with a star or a sticker, such as a good climbing tree, a sunny seat or the best place for snacks.', 'Add the people and animals you’ve met, such as a neighbour, a teacher or a friendly dog.', 'Mark a quiet place to go if you need a rest, and somewhere you’d like to explore next.', 'Add a title and a key that explains your symbols.'],
    prompts: ['What’s the first thing you see when you walk out the door?', 'Where’s your favourite spot so far?', 'It’s fine to leave gaps: you’re still exploring.', 'What would you like to find out about next?'],
    adapt: ['Young children: draw the walk from the gate to the classroom as a picture map, with an adult helping with labels.', 'Older adults moving into aged care: map the building, the garden and a favourite chair, and add the names of staff and neighbours.', 'Add a small map of the old place in one corner, if someone would like to keep it close.', 'Low vision: use thick markers on large paper, or make a touch map with string paths and textured stickers.', 'One-to-one: use a printed street map or floor plan as a base, and add drawings and stickers on top.'],
    reflect: ['What did you already know about your new place?', 'Which spot on your map do you like best?', 'What might you add to your map in a month’s time?'],
    care: `Moving can bring mixed feelings, including missing the old place, so welcome both. Don’t ask why someone moved, and keep maps general rather than showing exact addresses, especially in groups. ${CHILD_SAFE}` },
  { id: 'threads-of-connection', th: 'change', n: 'Threads of connection', sum: 'Wool threads linking you to the people, pets and places you carry with you.',
    mins: 45, who: 'Ages 7 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['textile', 'draw'],
    depth: 3,
    mat: ['A sturdy paper plate or a circle of thick card', 'Wool or embroidery thread in several colours', 'Felt-tips or coloured pencils', 'Child-safe scissors', 'Sticky tape', 'A sharp pencil, for an adult to make a hole'],
    purpose: 'When someone moves away, changes school or dies, the connection doesn’t simply disappear: memories, love and the things they taught us stay with us. Linking ourselves to the people, pets and places that matter with coloured threads gives that invisible connection something to see and touch.',
    steps: ['Draw yourself, your name or a simple symbol in the centre of the plate, and ask an adult to make a hole beside it with a sharp pencil.', 'Cut small snips about 1 cm deep all around the rim, a few centimetres apart.', 'Near the rim, draw small pictures or write names for the people, pets and places you feel connected to, including people far away or no longer here, if you choose.', 'Choose a colour of wool for each connection.', 'Tape the end of the wool to the back of the plate, bring it up through the centre hole, and take it out to a picture, hooking it into the snip beside it.', 'Bring the wool back to the centre and through the hole, ready to go out to the next picture.', 'Keep going, changing colours as you like, until every connection is linked to the centre, then tape the end at the back.', 'Hold up your plate and notice all the threads that lead to you.'],
    prompts: ['Who or what do you feel connected to, near or far?', 'People who are far away or no longer here can still have a thread.', 'Which colour suits this connection?', 'Notice how many threads lead to you.'],
    adapt: ['Young children: use big snips and chunky wool, with sticky tape wrapped around the end to make a stiff tip.', 'Groups: sit in a circle and pass a ball of wool across it, each person holding on and naming someone they feel connected to, then tape the web onto butcher’s paper.', 'Limited grip: use wide ribbon or fabric strips, taped in place rather than threaded.', 'Anyone who would rather keep names private can use colours or symbols only.', 'Low vision: use thick, textured wool and raised stickers so each connection can be felt.'],
    reflect: ['What was it like to see your connections all together?', 'Which thread did you most enjoy adding?', 'What did you notice when you held up your plate?'],
    care: `Let people decide who to include: friends far away, pets and places matter too. Some will add someone who has died, and strong feelings are normal; allow time, breaks and privacy, and don’t ask for details. In the group web, anyone can pass the wool on without speaking. Check in afterwards. ${CHILD_SAFE}` },
  { id: 'what-i-carry', th: 'change', n: 'What I carry with me', sum: 'A paper suitcase packed with the things that come with you into a new chapter.',
    mins: 45, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw', 'collage', 'words'],
    depth: 2,
    mat: ['A sheet of A4 card per person', 'A strip of card for the handle', 'Child-safe scissors and a glue stick', 'Felt-tips, textas and coloured pencils', 'Small pieces of paper for the things you pack', 'Stickers or washi tape (optional)'],
    purpose: 'Some of the most important things we take into a new school, a new home or life after a loss can’t be packed in a bag: memories, skills, love, family sayings and favourite songs. Filling a paper suitcase with them is a reassuring reminder that what matters most comes with us wherever we go.',
    steps: ['Fold the card in half with the fold at the bottom, round off the top corners, and glue a curved strip of card along the top edge as a handle.', 'Decorate the outside like a suitcase, with straps, buckles, a name tag and travel stickers.', 'Think about a change you’re heading into or living with, such as a new school, a new home, life between two homes, or missing someone.', 'Inside, draw or write the things you carry that no real bag could hold: memories, skills, people’s love, a favourite song, a family recipe, a language or a joke.', 'Make a few of them as small cut-out pictures to glue in, as if you’re packing.', 'Glue a paper pocket inside, open at the top, for anything you’d like to keep private.', 'Close the suitcase and, if you like, share one thing you packed.'],
    prompts: ['What do you take with you wherever you go?', 'What has someone taught you that you’ll always have?', 'Is there a smell, a song or a saying you’d pack?', 'You decide what to show and what to keep in the pocket.'],
    adapt: ['Young children: draw favourite people, pets and toys, plus one thing they’re good at.', 'Students new to Australia: pack languages, foods, festivals and stories from home.', 'Older adults: pack skills and stories from a long life, such as a trade, a recipe or a saying passed down.', 'Anyone who doesn’t want to draw can cut pictures from magazines or write a packing list.', 'Limited grip: use a pre-cut, pre-folded suitcase and glue sticks.'],
    reflect: ['What was the first thing you packed?', 'Which item feels most important to carry?', 'How might it feel to look inside your suitcase on a hard day?'],
    care: `Changes like separation, moving countries or a death in the family can sit behind this activity. Let people choose which change to think about, and don’t ask why it happened. The private pocket is for keeping, not checking. If someone becomes upset, offer a break or a lighter task, such as decorating the outside. ${CHILD_SAFE}` },
  { id: 'seasons-of-change', th: 'change', n: 'Seasons of change', sum: 'One tree painted through four seasons, as a gentle way to think about change.',
    mins: 50, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint', 'words'],
    depth: 2,
    mat: ['A3 watercolour or cartridge paper, folded into four panels', 'Watercolours or watered-down poster paint', 'Brushes, a jar of water and paper towels', 'A black felt-tip or oil pastel for the tree', 'Cotton buds for dabbing buds and blossom'],
    purpose: 'Seasons are a gentle way to think about change: leaves fall, branches rest, buds appear and the tree fills out again, and no season lasts forever. Painting one tree through autumn, winter, spring and summer lets people reflect on a change in their own lives as much or as little as they choose, or simply enjoy the colours.',
    steps: ['Fold the paper into four panels and draw the same simple tree in each, with a trunk and bare branches. A tree that loses its leaves, such as a plane tree or a fruit tree, works well.', 'Autumn: paint warm leaves falling and gathering on the ground. You might think about something that has ended or changed.', 'Winter: paint bare branches and a cool, quiet sky. You might think about in-between times, and what keeps you going when things feel bare.', 'Spring: dab on small buds and blossom with a cotton bud. You might think about the first small signs of something new.', 'Summer: fill the tree with leaves, fruit, birds or shade. You might think about what is growing now, or what you hope will grow.', 'If you like, write a word or two under each panel.', 'Stand the panels up like a folding screen and look at all four seasons together.'],
    prompts: ['You can think about a change in your life, or just paint the tree.', 'What colours does this season feel like?', 'What helps a tree get through winter?', 'Every season passes, and each one has something worth noticing.'],
    adapt: ['Young children: paint one season at a time over several classes, using fingertips and cotton buds for leaves and blossom.', 'Anyone who would rather not think about a personal change can paint the seasons they see from a window or in a favourite park.', 'Limited grip: use sponges or chunky brushes, and a printed tree outline.', 'Older adults: share memories of each season alongside the painting, such as summer holidays or frosty mornings.', 'Groups: paint one long shared tree on butcher’s paper, with each person adding to a season.'],
    reflect: ['Which season did you most enjoy painting?', 'What did you notice about the tree across the four panels?', 'How did you choose the colours for each season?'],
    care: `The tree can stir feelings about endings, so keep the personal thinking optional and never ask what each season stands for. If someone links a season to a loss, listen kindly without asking for details. Painting in order from autumn to summer means the session ends with growth and colour. ${CHILD_SAFE}` },
  { id: 'memory-lantern', th: 'change', n: 'Memory lantern', sum: 'A glowing paper lantern for someone or something remembered.',
    mins: 45, who: 'Ages 6 and up · one-to-one or small groups',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['collage', 'draw', 'words'],
    depth: 3,
    mat: ['Tracing paper or baking paper, about A4', 'Coloured tissue paper and a glue stick', 'Felt-tips, oil pastels or coloured pencils', 'A hole punch and child-safe scissors', 'Sticky tape', 'A battery tealight for each lantern (never a real flame)'],
    purpose: 'Light is part of remembering in many cultures and faiths. Making a lantern that glows with colours, symbols and words for someone or something remembered can be a calm way to hold love and memories, and gathering the lanterns together offers a quiet moment of connection.',
    steps: ['Think about who or what your lantern is for: a person, a pet, a place, or a friend who moved away.', 'Tear small pieces of tissue paper in colours that remind you of them, and glue them onto the tracing paper, overlapping some.', 'Draw symbols, patterns or small pictures on top, such as a favourite flower, a paw print or a place you shared.', 'Add a name, a word or a short message if you like, such as “I remember…” or “Thank you for…”.', 'Punch holes along the top and bottom edges so little points of light will shine through.', 'Roll the paper into a tube, overlapping the edges a little, and tape it closed.', 'Check that the tealight’s battery cover is firmly closed, switch it on, and stand the lantern over it.', 'If the group would like to, dim the lights and place the lanterns together for a quiet moment, saying a name aloud or silently.', 'Turn the lights back on and finish with something light, such as a stretch or sharing a favourite food.'],
    prompts: ['Who or what would you like your lantern to be for?', 'What colours remind you of them?', 'You can say a name aloud, think it quietly, or just watch the light.', 'Happy memories are welcome here too.'],
    adapt: ['Young children: decorate paper with the holes already punched, using felt-tips and stickers, and an adult tapes the tube.', 'Anyone who finds rolling paper fiddly can glue tissue paper onto a clean, clear plastic jar instead.', 'Use a symbol rather than a name if a family’s customs avoid naming people who have died.', 'Families may have their own ways of remembering with light; welcome these, and let students share them if they wish.', 'Anyone who would rather not think about a loss today can make a lantern for a place they love or a happy time.'],
    reflect: ['What did you enjoy about making your lantern?', 'What was it like to see it glow?', 'Where might you put your lantern at home?'],
    care: `Use battery tealights only, never real flames, and keep them away from young children, as button batteries are dangerous if swallowed. People choose who or what to remember; focus on memories and love, never on how someone died. Tears and quiet are normal: let people step out, and check in afterwards. ${CHILD_SAFE}` },
  { id: 'new-chapter-capsule', th: 'change', n: 'Time capsule for a new chapter', sum: 'Capturing life right now in a sealed capsule, to open after a big change.',
    mins: 50, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['words', 'draw', 'collage'],
    depth: 2,
    mat: ['A container to seal, such as a cardboard tube, a clean jar or a large envelope', 'Paper, card and small envelopes', 'Felt-tips, textas and coloured pencils', 'Collage papers, stickers and a glue stick', 'Ribbon or string, and sticky tape'],
    purpose: 'A new chapter, such as starting high school, moving, a new baby in the family or retiring, is worth marking. Filling a time capsule with drawings and notes about life right now, and hopes for what comes next, turns the change into something to look forward to and makes a gift for a future self.',
    steps: ['Name the new chapter: starting school or high school, moving, a new sibling, a new job, retiring, or simply a new year.', 'Make a “right now” page: draw yourself and your favourite things, foods, songs, people and places.', 'Trace your hand on card and write the date on it, to compare when the capsule is opened.', 'Write a short letter to your future self about what you’re looking forward to, what you’re unsure about, and a question you’d like answered.', 'Add a drawing of where you live or learn now, and a small flat keepsake if you have one, such as a ticket or a photo.', 'Decorate the container and label it with your name and an opening date, such as six months or a year from now.', 'Seal it with tape or ribbon, and agree where it will be kept until then.'],
    prompts: ['What’s life like for you right now?', 'What are you looking forward to in this new chapter?', 'What would you like your future self to remember about today?', 'It’s OK to feel excited and nervous at the same time.'],
    adapt: ['Young children: fill in a simple page of favourites with drawings, and an adult writes their words.', 'Groups finishing a year together: make one class capsule with a page from everyone.', 'Older adults retiring or moving: add stories, recipes or advice for the future, or for a grandchild to read one day.', 'Anyone who doesn’t want to write can draw instead, or say their words to an adult who writes them down.'],
    reflect: ['What was it like to describe your life right now?', 'What do you think will have changed when you open it?', 'What are you most looking forward to?'],
    care: `Not every new chapter is welcome, and a move or a family change may feel hard, so let people choose what to include and what to leave out. Keep letters sealed and private. Agree where capsules will be stored, preferably at home, and note the opening date so it isn’t forgotten. ${CHILD_SAFE}` },
  { id: 'mended-with-gold', th: 'change', n: 'Mended with gold', sum: 'Tearing a paper bowl and mending its cracks with gold, inspired by kintsugi.',
    mins: 60, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint', 'collage'],
    depth: 2,
    mat: ['A plain, uncoated paper bowl or paper plate per person', 'Paint, felt-tips or paint pens for decorating', 'Masking tape and PVA glue', 'Gold paint and a fine brush, or a gold paint pen', 'A sheet of card (for the plate version)', 'Photos of kintsugi pottery (optional)'],
    purpose: 'Kintsugi is a Japanese tradition of mending broken pottery with lacquer and powdered gold, so the repair becomes part of the object’s beauty instead of being hidden. Making a paper version is a gentle way to think about how things that change or break can be cared for, and become part of a story.',
    steps: ['Talk about kintsugi and, if you can, look at photos of mended bowls with golden seams.', 'Decorate your paper bowl with paint or felt-tips, inside and out, and let it dry.', 'When you’re ready, tear the bowl into three to five large pieces, slowly or quickly, however feels right.', 'Fit the pieces back together and join them on the inside with small strips of masking tape.', 'Brush a thin layer of PVA glue over the tape to make the joins stronger, and let it dry.', 'Paint over every crack on the outside with gold, letting the lines be as wide and wobbly as they are.', 'Add gold along the seams inside too, and leave the bowl to dry.', 'If you like, write a small word along one seam about something that helps when things change, such as a person, a place or a habit.', 'Hold the bowl up and notice how the gold lines catch the light.'],
    prompts: ['The cracks are the part we’re going to make beautiful.', 'Tear it slowly or quickly, whatever feels right.', 'What helps you when something changes?', 'Look at the path each gold line takes.'],
    adapt: ['Paper plate version: tear the plate, glue the pieces onto card with small gaps between them, and paint gold into the gaps.', 'Young children: an adult starts each tear, and children join the pieces with gold washi tape.', 'Anyone who finds it hard to tear their own work can tear a plain bowl, or mend one the teacher has torn.', 'Limited grip: tear strips of masking tape in advance and stick them along the table edge, and use a chunky gold paint pen.', 'Older students: make a papier-mâché bowl in an earlier class, then tear and mend it.'],
    reflect: ['What was it like to tear something you had decorated?', 'How does the bowl look to you now, with its gold lines?', 'Which part of mending it did you enjoy most?'],
    care: `Never break real pottery in class. Use the idea of breaking lightly, and never describe a person, a body or a family as broken; families that have separated aren’t broken. Personal reflection is optional, and the making alone is enough. If tearing feels upsetting, offer a bowl to mend that someone else has torn. ${CHILD_SAFE}` },
  { id: 'roots-and-new-shoots', th: 'change', n: 'Roots and new shoots', sum: 'A collage plant with roots from the old place and new shoots in the new one.',
    mins: 35, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['collage', 'words'],
    depth: 2,
    mat: ['A sheet of card, A4 or A3', 'Brown wool or string for the roots', 'Green and coloured paper or tissue paper for leaves and shoots', 'A glue stick and PVA glue', 'Child-safe scissors', 'Felt-tips or textas'],
    purpose: 'When a gardener moves a plant, it brings its roots along, often droops for a little while, then settles in and sends out new shoots. That makes it a hopeful picture for moving house, school or country: what we bring from the old place keeps us going, and new things can grow in time.',
    steps: ['Talk about what happens when a plant is moved to a new garden: it brings its roots, may droop for a while, and then starts to grow again.', 'Draw or collage a pot or a patch of ground across the middle of the card to stand for the new place.', 'Glue lengths of brown wool below it as roots, spreading them out in different directions.', 'Label each root with something from the old place that still helps you, such as family, friends, a language, a skill or a memory.', 'Add a stem above the ground with a few leaves, and on each leaf draw or write something that’s already good about the new place.', 'Add small buds or new shoots for things you hope will grow, such as a new friend, a club or a favourite spot.', 'Add sun, rain or a watering can for the people and things that help you settle in.'],
    prompts: ['What did you bring with you that still helps?', 'What’s already growing in your new place?', 'It’s normal to droop a bit after a move. Plants do too.', 'What would you like to grow next?'],
    adapt: ['Young children: make a flower with three roots and three leaves, with an adult writing their words.', 'Students new to Australia: give roots to languages, festivals and family overseas, and leaves to new words and new friends.', 'Older adults moving into aged care: roots for family, work and community, and shoots for new routines and friendships.', 'Limited grip: use pre-cut leaves and lengths of wool, with glue sticks.', 'Anyone who doesn’t want to write can use colours and pictures only.'],
    reflect: ['Which root was easiest to name?', 'What did you notice when you looked at the roots and shoots together?', 'What helps you feel settled?'],
    care: `Moves aren’t always chosen: some follow a separation, hard times or arriving as a refugee. Don’t ask why someone moved, keep labels private if preferred, and accept a drooping plant just as it is. ${CHILD_SAFE}` },

  /* ---------- more calm and grounding ---------- */
  { id: 'glitter-calm-jar', th: 'calm', n: 'Calm-down glitter jar', sum: 'A sealed jar of swirling glitter to shake, then watch as it slowly settles.',
    mins: 30, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 3,
    media: ['mixed'],
    depth: 1,
    mat: ['A clear plastic bottle or jar with a screw-top lid (never glass)', 'Clear glue or glitter glue, and warm water in a jug', 'Fine glitter, biodegradable if possible, plus sequins or small stars', 'A funnel and a teaspoon', 'Food colouring (optional)', 'Strong glue and electrical tape for sealing (adult use only)'],
    purpose: 'Shaking a glitter jar and watching the sparkle swirl, then slowly settle, gives busy thoughts something calm to follow and a natural pause for a few slow breaths. Making their own jar, in colours they choose, gives students a calming tool to keep and use whenever they need it.',
    steps: ['Peel off any labels and fill the bottle about a quarter full with clear glue or glitter glue, using the funnel.', 'Top it up with warm water, leaving a small gap at the top, then put the lid on and shake until the glue mixes in.', 'Add a teaspoon of fine glitter and a pinch of sequins or stars, in colours you love.', 'Add one drop of food colouring if you like, keeping the water light enough to see the glitter.', 'Shake the bottle and count how long the glitter takes to settle. Add more glue to slow it down, or more warm water to speed it up.', 'When it’s just right, an adult glues the lid on firmly and wraps tape around it.', 'Shake the jar, then breathe slowly while the glitter drifts down, until the water is clear again.'],
    prompts: ['Watch one piece of glitter all the way to the bottom.', 'Breathe slowly while it settles.', 'When thoughts feel swirly, a few minutes of watching can help them settle too.', 'Where could you keep your jar so it’s handy when you need it?'],
    adapt: ['Young children: use a small bottle and pre-measured cups of glue, water and glitter, with an adult pouring.', 'Teens and adults: try a slim bottle with one colour of fine glitter for a subtle desk jar.', 'Limited grip: use a wide-mouthed jar, and let the student choose and spoon while an adult pours.', 'Sensory-sensitive participants who dislike glitter on their hands can spoon it through the funnel, or use beads and sequins only.', 'Low vision: choose large, bright sequins and a contrasting water colour, and watch against a plain, light background.'],
    reflect: ['How long did your glitter take to settle?', 'What did you notice while you watched it?', 'When might you use your jar?'],
    care: 'Use plastic, never glass. An adult seals every lid with strong glue and tape, and checks for leaks before the jar goes home. Keep glitter away from eyes and mouths, and keep jars away from children under 3. Wipe up spilt glitter with a damp cloth and put it in the rubbish, not down the sink.' },
  { id: 'slow-stitching', th: 'calm', n: 'Slow stitching', sum: 'Rows of simple running stitch on hessian, made at an unhurried pace.',
    mins: 45, who: 'Ages 7 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['textile'],
    depth: 1,
    mat: ['A square of hessian or loosely woven fabric, about 20 cm', 'An embroidery hoop (optional)', 'Blunt tapestry needles with large eyes, and a needle threader', 'Embroidery thread or thin wool in several colours', 'Child-safe scissors and a pincushion', 'Chalk for marking a starting line (optional)'],
    purpose: 'Running stitch is one of the simplest stitches there is: up through the fabric, along a little, and down again. Repeating it slowly, with no pattern to follow and no need to finish, gives the hands a steady rhythm and lets the mind rest on one small, quiet task, while the rows build into a soft, textured piece.',
    steps: ['Fit the hessian into the hoop if you’re using one, pulling it gently tight like a drum.', 'Thread the needle with about an arm’s length of thread, and tie a knot at the long end.', 'Bring the needle up from the back, go down a little further along, then up again: this is running stitch.', 'Keep going in a line across the fabric, letting each stitch be whatever length feels right.', 'Follow the weave for straight rows, or let the line wander in curves, waves or a spiral.', 'Notice the sound of the thread pulling through and the feel of the needle going up and down.', 'When the thread runs short, take it to the back, tie a small knot or weave it under a few stitches, and start again in a new colour.', 'Stop wherever you like: the piece can grow over several sessions.'],
    prompts: ['Up, along and down. There’s no hurry.', 'Wobbly stitches are part of the charm.', 'Listen to the thread pulling through.', 'You can stop whenever you like and pick it up again next time.'],
    adapt: ['Young children: stitch chunky wool with a plastic needle through pre-punched card or plastic canvas.', 'Low vision or limited dexterity: use a large-eyed needle and a needle threader, thick bright wool, and fabric fixed in a hoop or taped to a frame.', 'Experienced stitchers: layer two scraps of fabric and join them with rows of running stitch, in the spirit of Japanese sashiko or Bengali kantha.', 'Older adults who have sewn before: invite them to share tips, and offer finer fabric and thread if they’d like.', 'One-to-one: stitch alongside the student in companionable quiet, or chat while you both work.'],
    reflect: ['What did you notice as the stitches added up?', 'Which colours or lines did you enjoy most?', 'How did it feel to stitch slowly, without a plan?'],
    care: 'Count needles out and back in, keep them in a pincushion between uses, and supervise scissors. Use blunt tapestry needles with children, and keep needles and thread away from children under 3. Tangles and knots happen to everyone: help calmly and early, so frustration doesn’t take over.' },
  { id: 'stamp-and-repeat', th: 'calm', n: 'Stamp and repeat', sum: 'Printing rows of repeated shapes with everyday objects, in a steady rhythm.',
    mins: 30, who: 'All ages · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['print'],
    depth: 1,
    mat: ['Clean objects to stamp with, such as corks, lids, cotton reels and blocks', 'Washable paint or block printing ink', 'Paper plates, plus a folded paper towel or sponge to use as an ink pad', 'Cartridge paper, coloured paper or brown wrapping paper', 'Aprons and wet wipes', 'Foam printing sheets and blunt pencils (optional)'],
    purpose: 'Dipping, pressing and lifting the same small object, over and over, settles into a steady rhythm that can quieten a busy mind. Each print comes out a little different, so there’s no such thing as a perfect one, and turning the stamp or changing colour keeps the pattern interesting without needing a plan.',
    steps: ['Spread a thin layer of paint on a plate and press a folded paper towel or sponge into it to make an ink pad.', 'Choose two or three objects and try a test print of each on scrap paper.', 'Start at one edge of the page: dip, press, lift, then move along a little and do it again.', 'Find a steady rhythm, perhaps saying “dip, press, lift” quietly, or breathing out with each press.', 'Fill the row, then start the next one underneath: repeat the same shape, alternate two shapes, turn the stamp, or change colour.', 'Keep going until the page is full, or until it feels finished.', 'Step back and look at the whole pattern, as if it were fabric or wrapping paper.'],
    prompts: ['Dip, press, lift. Find your rhythm.', 'Every print is a little different, and that’s part of it.', 'What happens if you turn the stamp a quarter turn each time?', 'Listen to the soft sound each press makes.'],
    adapt: ['Young children: use chunky objects like blocks and cardboard tubes on a big sheet of butcher’s paper.', 'Teens and adults: draw a simple design into a foam printing sheet with a blunt pencil, then print it in rows, half-drops or rotations.', 'Limited grip: glue a cotton reel or bottle lid to the back of a stamp as a knob, or use large sponge shapes.', 'Sensory-sensitive participants: use stamps with handles to keep fingers clean, and keep wet wipes close by.', 'Groups: print a long shared strip of wrapping paper or bunting, with each person adding a row.'],
    reflect: ['Which stamp did you enjoy using most?', 'What was it like to find a rhythm?', 'What do you notice when you look at the whole page?'],
    care: 'Check that found objects are clean and safe to use, and ask about allergies before using food items such as potato or apple stamps. Keep small stamps like lids and blocks away from children under 3, and use washable paint with young children.' },
  { id: 'finger-labyrinth', th: 'calm', n: 'Finger labyrinth', sum: 'Drawing a simple labyrinth, then tracing its winding path slowly in and out.',
    mins: 25, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['Scrap paper for practising, and A4 paper or card', 'A pencil and an eraser', 'Felt-tips, textas or coloured pencils', 'Printed labyrinths to trace (optional)'],
    purpose: 'A labyrinth is not a maze: it has one winding path to the centre and no dead ends, so there’s nothing to solve and no way to get lost. The classical design drawn here is thousands of years old and appears in many cultures. Tracing its turns slowly with a fingertip, in and back out, is a quiet way to slow down and focus.',
    steps: ['Practise on scrap paper first. In the lower half of the page, draw a cross about 4 cm wide, then put a dot in each corner between its arms, as if the cross sat inside a square.', 'Join the top of the cross to the top-right dot with a small arch.', 'Join the top-left dot to the right arm of the cross with an arch that loops over the first one.', 'Join the left arm of the cross to the bottom-right dot with a bigger arch over the top of both.', 'Join the bottom-left dot to the bottom of the cross with the biggest arch, all the way round the outside. The gap left at the bottom is the entrance.', 'Once it works, draw it large on good paper, go over the lines in felt-tip, and colour the walls or the path if you like.', 'Rest a fingertip at the entrance and trace slowly along the path to the centre, breathing naturally.', 'Pause in the centre for a breath or two, then follow the same path slowly back out.'],
    prompts: ['There’s only one path, so you can’t get lost.', 'Go as slowly as you can, as if your finger is walking.', 'Notice each turn, where the path doubles back on itself.', 'Rest in the centre for a breath before you head back out.'],
    adapt: ['Young children: trace a large printed labyrinth with a finger or a toy car, and colour the path.', 'Low vision or limited grip: glue wool along the lines of a large printed labyrinth so the walls can be followed by touch.', 'Groups with outdoor space: draw a giant labyrinth in chalk on a playground or path, and walk it slowly together.', 'Anyone who finds the drawing steps frustrating can trace a ready-made labyrinth; the slow tracing is the main part.', 'Older students: once three circuits feel easy, try a seven-circuit labyrinth from a printed guide.'],
    reflect: ['What was it like to build the labyrinth from a cross and four dots?', 'How did it feel to trace the path slowly?', 'Did the way out feel different from the way in?'],
    care: 'Drawing the labyrinth can be fiddly at first, so keep printed copies ready and reassure people that wobbly versions work perfectly well. If the stillness of tracing feels uncomfortable for anyone, let them trace with a pencil, hum quietly or stop whenever they like.' },
  { id: 'ocean-wave-washes', th: 'calm', n: 'Ocean wave washes', sum: 'Slow bands of watercolour sea, painted in time with the sound of waves.',
    mins: 35, who: 'All ages · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint'],
    depth: 1,
    mat: ['Watercolour paper or thick cartridge paper, taped to a board', 'Watercolours or liquid watercolour in blues, greens and a sandy colour', 'A wide soft brush and a smaller round brush', 'Two jars of water, paper towels and tissues', 'A recording of gentle waves (optional)'],
    purpose: 'Long, slow brush strokes in time with the sound of waves give the arm, the eyes and the breath one steady rhythm to follow. Watercolour spreads and softens by itself, so the painting needs very little control, and many people find the endless coming and going of the sea calming to watch, hear and paint.',
    steps: ['Play a recording of gentle waves, or describe a calm beach, and listen for a minute to the rhythm of the water.', 'Lightly pencil a horizon line a third of the way down. Brush a pale wash of sky above it, and listen while it dries a little.', 'Load the wide brush with deep blue and pull one long, slow stroke across the page just below the horizon, in time with a wave rolling in.', 'Rinse, then paint the next band a little lower in a lighter blue or green, letting it touch the wet band above so the colours soften together.', 'Keep adding bands down the page, paler and greener as the water gets shallower, and finish with a strip of sandy shore if you like.', 'While the paint is still damp, press a scrunched tissue along the top edge of a few bands to lift out white lines of foam.', 'Put the brushes down and listen to the waves for one more minute while the painting dries.'],
    prompts: ['Listen for a wave coming in, and let your brush come in with it.', 'Slow strokes, all the way across.', 'Let the colours run into each other.', 'Which beach or stretch of water would you like to paint?'],
    adapt: ['Young children: use liquid watercolour and a wide sponge brush, and paint to the sound of the waves without worrying about bands.', 'Limited grip: use a wide foam brush with a chunky handle, or a sponge held in the whole hand.', 'Anyone who doesn’t find the sea calming can paint a still lake, a river or a wide evening sky in the same slow bands.', 'Sensory-sensitive participants: keep the wave sound soft, or paint in quiet.', 'Older adults: share memories of favourite beaches, rivers or swims while the paint dries, if they wish.'],
    reflect: ['What was it like to paint in time with the waves?', 'What happened where the wet colours met?', 'How does your body feel now compared with the start?'],
    care: 'The sea isn’t calming for everyone: some people have had frightening experiences with water or floods, or simply dislike it, so offer the lake or sky version without needing a reason. Keep the sound low, and turn it off if anyone finds it unsettling.' },
  { id: 'colour-breathing-squares', th: 'calm', n: 'Colour breathing squares', sum: 'Painting one side of a square for each slow count of in, hold, out and hold.',
    mins: 15, who: 'Ages 7 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint'],
    depth: 1,
    mat: ['A square of thick paper or card, about 20 cm', 'Watercolours, gouache or poster paint in three or four colours', 'A small flat brush', 'A jar of water and paper towels'],
    purpose: 'In box breathing, you breathe in, hold, breathe out and hold again, each for the same slow count. Painting one side of a square for each part of the breath gives the counting a shape and a colour to follow, and the nested squares that build up make a calm, pleasing picture to keep.',
    steps: ['Sit comfortably with your feet on the floor, and take two ordinary breaths.', 'Load the brush with your first colour and rest it near the top-left corner of the paper, just in from the edge.', 'Breathe in for a slow count of four as you paint along the top.', 'Hold for four as you paint down the right side, breathe out for four along the bottom, and hold for four up the left side to close the square.', 'Choose a new colour and paint a slightly smaller square just inside the first, with the same slow breathing.', 'Keep going, one square for each breath, changing colour each time, until you reach a small square in the centre.', 'Rest the brush, breathe normally, and look at the colours sitting side by side.'],
    prompts: ['In for four along the top. Hold for four down the side.', 'Let the brush move as slowly as the count.', 'If holding your breath feels uncomfortable, just breathe slowly and keep painting.', 'Which colour would you like for the next breath?'],
    adapt: ['Young children: count to three instead of four, and leave out the holds if they’re tricky.', 'Anyone who finds holding the breath uncomfortable can breathe in along two sides and out along the other two.', 'Limited grip: use a chunky brush or a thick felt-tip on a larger sheet taped to the table.', 'Older students: afterwards, look at Josef Albers’s Homage to the Square paintings and notice how neighbouring colours seem to change each other.', 'Groups: use it as a short settling activity at the start or end of a class.'],
    reflect: ['How did your breathing feel by the last square?', 'Was it easier to paint slowly or to count slowly?', 'Which colours did you enjoy putting side by side?'],
    care: 'Keep the breathing gentle and the holds short and optional. Anyone who feels light-headed, anxious or short of breath should stop and breathe normally. Breath-focused exercises don’t suit everyone, including some people with asthma, so offer slow painting to quiet music or simple counting instead.' }
    );
